#include <iostream>
#include <memory>
int main() {
    auto sp = std::make_shared<int>(99);
    std::weak_ptr<int> wp = sp;
    std::cout << wp.expired() << '\n';           // 还活着 → 0
    if (auto lk = wp.lock()) std::cout << *lk << '\n';
    sp.reset();                                   // 对象被销毁
    std::cout << wp.expired() << '\n';           // 已死 → 1
    std::cout << (wp.lock() == nullptr);         // lock 返回空
}
